#include "urban_internal.h"
static struct NativeEntity*factory(struct WeaponWorld*w,struct NativeEntity*e,unsigned kind){struct PlayerTransform t=e->payload.enemy.actor.transform;t.display_group=e->payload.enemy.source_flags;if(kind>=URFX_LOCAL0&&kind<=URFX_LOCAL5)return urban_debris_spawn(w,entity_ref(e),ENTITY_LAST_CHILD,&t,kind-URFX_LOCAL0);if(kind<=URFX_BLAST)return boss_fx_spawn(w,entity_ref(e),ENTITY_LAST_CHILD,&t,(enum BossFxKind)(BFX_SMALL+kind));if(kind>=URFX_DEBRIS0&&kind<=URFX_DEBRIS7)return boss_fx_spawn(w,entity_ref(e),ENTITY_LAST_CHILD,&t,(enum BossFxKind)(BFX_DEBRIS0+kind-URFX_DEBRIS0));enemy_fault(w);return 0;}
static int pattern(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy,*p=op_parent(w,e);if(!p)return 0;struct WeaponActor*a=&q->actor;q->scale_x=p->scale_x;q->scale_y=p->scale_y;const struct BossPatternData*t=&urban_patterns[q->urban.pattern];int emit=q->urban.delay==255;if(!emit&&!--q->urban.delay){q->urban.delay=t->period;emit=1;}
 if(emit){if(t->follow){int16_t dx=p->actor.transform.facing&1?op_word(-t->dx):t->dx,dy=p->actor.transform.facing&1?op_word(-t->dy):t->dy;transform_integer_offset(&a->transform,op_word((p->actor.transform.x>>8)+dx-(a->transform.x>>8)),op_word(transform_y_up(&p->actor.transform)+dy-transform_y_up(&a->transform)));}for(unsigned budget=0;budget<ENTITY_CAPACITY;budget++){unsigned kind=t->random?urban_pattern_choices[q->urban.pattern][vg_bounded(w,16)]:t->kind;struct NativeEntity*n=factory(w,e,kind);if(!n)return 0;int16_t dx=vg_bounded(w,t->spread_x),dy=vg_bounded(w,t->spread_y);if(a->transform.facing&1)dx=op_word(-dx);if(a->transform.facing&2)dy=op_word(-dy);transform_integer_offset(&n->payload.enemy.actor.transform,dx,dy);n->payload.enemy.actor.display_flags|=a->display_flags&64;n->payload.enemy.scale_x=q->scale_x;n->payload.enemy.scale_y=q->scale_y;if(q->urban.delay!=255)break;if(!--q->urban.remaining){entity_delete(w->entities,e);return !w->fault;}if(budget==ENTITY_CAPACITY-1)return enemy_fault(w);}}if(!--q->urban.remaining)entity_delete(w->entities,e);return !w->fault;
}
static unsigned bounds(unsigned v){return v==1||v==4||v==5?4:5;}
int ur_fx_enter(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;unsigned s=a->state;
 if(s==UR_PATTERN){if(q->urban.pattern>=URP_COUNT)return enemy_fault(w);q->urban.delay=urban_patterns[q->urban.pattern].period;q->urban.remaining=urban_patterns[q->urban.pattern].life;return 1;}
 if(s==UR_BLINK_A||s==UR_BLINK_B){if(!vg_cycle(w,0x48,s==UR_BLINK_A?0x79:0x78,s==UR_BLINK_A?2:1))return 0;q->urban.clock=s==UR_BLINK_A?64:32;return 1;}
 if(s!=UR_DEBRIS||q->urban.variant>6)return enemy_fault(w);unsigned v=q->urban.variant;ur_start_entry(q,urban_debris[v==6?2:v]);a->palette=v==6?0xad:0x9e;q->scale_x=q->scale_y=255;a->transform.facing|=vg_random(w)&1;a->vy=2040;a->ay=-68;a->ax=0;a->vx=vg_bounded(w,1023);if(a->vx&1)a->vx=op_word(-a->vx);uint16_t r=vg_bounded(w,2047);a->vy=op_word(a->vy-r);a->transform.facing|=r&1;if(interaction_outside(w,a,boss_fx_bounds[bounds(v)],1)){entity_delete(w->entities,e);return 0;}ur_defense(q,65535);return !w->fault;
}
int ur_fx_frame(struct WeaponWorld*w,struct NativeEntity*e,unsigned s){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;if(s==UR_PATTERN)return pattern(w,e);if(s==UR_BLINK_A||s==UR_BLINK_B){if(!--q->urban.clock)ur_schedule(e,s==UR_BLINK_A?UR_BLINK_B:UR_BLINK_A);if(!w->mission_valid)return enemy_fault(w);if((int16_t)w->mission_progress>=768)entity_delete(w->entities,e);return !w->fault;}if(s!=UR_DEBRIS)return enemy_fault(w);if(a->vy<=-1280)a->vy=-1279;if(interaction_move(w,a,WMOVE_POINT)<0)return 0;int done=0;if(boss_sprite_admitted(w))done=ur_animate(w,e);if(done||interaction_outside(w,a,boss_fx_bounds[bounds(q->urban.variant)],1))entity_delete(w->entities,e);return !w->fault;}
